import { createContext, useContext, useMemo, useReducer } from "react";
import type { ReactNode } from "react";

const CartContext = createContext<CartValue | null>(null);

export function CartProvider({ children }: { children: ReactNode }) {
  const [items, dispatch] = useReducer(cartReducer, []);
  // Memoized, yet a new object every time items change
  const value = useMemo(() => ({ items, dispatch }), [items]);
  return <CartContext value={value}>{children}</CartContext>;
}

export function AddToCartButton({ id }: { id: string }) {
  const { dispatch } = useContext(CartContext)!; // renders on every add
  return (
    <button onClick={() => dispatch({ type: "add", id })}>Add to cart</button>
  );
}

import { createContext, useContext, useReducer } from "react";
import type { ReactNode } from "react";

const CartContext = createContext<CartItem[]>([]);
const CartDispatchContext = createContext<CartDispatch>(() => {});

export function CartProvider({ children }: { children: ReactNode }) {
  const [items, dispatch] = useReducer(cartReducer, []);
  return (
    <CartContext value={items}>
      <CartDispatchContext value={dispatch}>{children}</CartDispatchContext>
    </CartContext>
  );
}

export function AddToCartButton({ id }: { id: string }) {
  const dispatch = useContext(CartDispatchContext); // never changes
  return (
    <button onClick={() => dispatch({ type: "add", id })}>Add to cart</button>
  );
}
